/**
 * OErrorBoundaryPage — 应用级错误兜底页。
 *
 * 配合 React ErrorBoundary 使用:
 *   <ErrorBoundary fallback={(err) => <OErrorBoundaryPage error={err} onReset={...} />}>
 */
import type { ReactNode } from 'react';

export interface OErrorBoundaryPageProps {
  title?: string;
  error?: Error | { message?: string; stack?: string };
  /** 项目重置回调。 */
  onReset?: () => void;
  /** 是否显示 stack(默认 false,生产关闭)。 */
  showStack?: boolean;
  homeLink?: ReactNode;
}

export default function OErrorBoundaryPage({
  title = '应用出错',
  error,
  onReset,
  showStack,
  homeLink,
}: OErrorBoundaryPageProps) {
  const message = error?.message ?? '未知错误';
  return (
    <div
      role="alert"
      aria-labelledby="oui-err-title"
      className="min-h-screen flex flex-col items-center justify-center px-4 py-12 bg-background text-foreground @container"
    >
      <div className="text-center max-w-lg">
        <div className="text-5xl mb-4" aria-hidden="true">⚠</div>
        <h1 id="oui-err-title" className="text-xl font-semibold mb-2">
          {title}
        </h1>
        <p className="text-sm text-muted-foreground mb-4">{message}</p>
        {showStack && error?.stack && (
          <pre className="text-left text-[10px] font-mono bg-muted text-muted-foreground p-3 rounded mb-4 overflow-auto max-h-48">
            {error.stack}
          </pre>
        )}
        <div className="flex items-center justify-center gap-2">
          {onReset && (
            <button
              type="button"
              onClick={onReset}
              className="px-4 py-2 text-sm rounded bg-primary text-primary-foreground hover:opacity-90"
            >
              重试
            </button>
          )}
          {homeLink}
        </div>
      </div>
    </div>
  );
}
