/**
 * OMembersPage — 团队 / 组织成员管理。
 *
 * 接收 members 列表 + 回调,Page 不实现 RBAC 守卫(项目自管)。
 */
import { useState, type ReactNode } from 'react';

export interface Member {
  id: string;
  email: string;
  displayName?: string;
  role: string;
  joinedAt?: string | Date;
  avatarUrl?: string;
  status?: 'active' | 'invited' | 'suspended';
}

export interface OMembersPageProps {
  members: Member[];
  roleOptions?: { value: string; label: string }[];
  /** 是否允许邀请。 */
  canInvite?: boolean;
  /** 是否允许编辑角色。 */
  canEditRole?: boolean;
  /** 是否允许移除成员。 */
  canRemove?: boolean;
  onInvite?: (data: { email: string; role: string }) => void | Promise<void>;
  onRoleChange?: (memberId: string, newRole: string) => void | Promise<void>;
  onRemove?: (memberId: string) => void | Promise<void>;
  title?: string;
  /** 顶部 actions slot。 */
  actionsSlot?: ReactNode;
}

export default function OMembersPage({
  members,
  roleOptions = [
    { value: 'owner', label: 'Owner' },
    { value: 'admin', label: 'Admin' },
    { value: 'member', label: 'Member' },
    { value: 'viewer', label: 'Viewer' },
  ],
  canInvite = true,
  canEditRole = true,
  canRemove = true,
  onInvite,
  onRoleChange,
  onRemove,
  title = '成员',
  actionsSlot,
}: OMembersPageProps) {
  const [inviteOpen, setInviteOpen] = useState(false);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState(roleOptions[0]?.value ?? 'member');

  const submitInvite = (e: React.FormEvent) => {
    e.preventDefault();
    onInvite?.({ email: inviteEmail, role: inviteRole });
    setInviteEmail('');
    setInviteOpen(false);
  };

  return (
    <div className="flex flex-col h-full @container">
      <header className="flex items-center justify-between px-6 py-4 border-b border-border">
        <div>
          <h1 className="text-xl font-semibold">{title}</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            共 {members.length} 个成员
          </p>
        </div>
        <div className="flex items-center gap-2">
          {actionsSlot}
          {canInvite && (
            <button
              type="button"
              onClick={() => setInviteOpen((v) => !v)}
              className="px-3 py-1.5 text-sm rounded bg-primary text-primary-foreground hover:opacity-90"
            >
              + 邀请成员
            </button>
          )}
        </div>
      </header>

      {inviteOpen && (
        <form
          onSubmit={submitInvite}
          className="flex items-center gap-2 px-6 py-3 border-b border-border bg-muted/30"
        >
          <input
            type="email"
            required
            placeholder="邮箱"
            value={inviteEmail}
            onChange={(e) => setInviteEmail(e.target.value)}
            className="flex-1 px-3 py-1.5 text-sm rounded border border-border bg-input"
          />
          <select
            value={inviteRole}
            onChange={(e) => setInviteRole(e.target.value)}
            aria-label="角色"
            className="px-2 py-1.5 text-sm rounded border border-border bg-input"
          >
            {roleOptions.map((r) => (
              <option key={r.value} value={r.value}>
                {r.label}
              </option>
            ))}
          </select>
          <button
            type="submit"
            className="px-3 py-1.5 text-sm rounded bg-primary text-primary-foreground"
          >
            邀请
          </button>
          <button
            type="button"
            onClick={() => setInviteOpen(false)}
            className="px-3 py-1.5 text-sm rounded border border-border"
          >
            取消
          </button>
        </form>
      )}

      <div className="flex-1 overflow-auto">
        <table className="w-full text-sm">
          <thead className="border-b border-border bg-muted/30 sticky top-0">
            <tr>
              <th className="text-left px-6 py-2 font-medium text-muted-foreground text-xs">成员</th>
              <th className="text-left px-6 py-2 font-medium text-muted-foreground text-xs">角色</th>
              <th className="text-left px-6 py-2 font-medium text-muted-foreground text-xs">加入时间</th>
              <th className="text-left px-6 py-2 font-medium text-muted-foreground text-xs">状态</th>
              <th className="px-6 py-2">
                <span className="sr-only">操作</span>
              </th>
            </tr>
          </thead>
          <tbody>
            {members.map((m) => (
              <tr key={m.id} className="border-b border-border hover:bg-muted/30">
                <td className="px-6 py-3">
                  <div className="flex flex-col">
                    <span className="font-medium">{m.displayName ?? m.email}</span>
                    {m.displayName && (
                      <span className="text-xs text-muted-foreground">{m.email}</span>
                    )}
                  </div>
                </td>
                <td className="px-6 py-3">
                  {canEditRole ? (
                    <select
                      value={m.role}
                      onChange={(e) => onRoleChange?.(m.id, e.target.value)}
                      aria-label={`${m.email} 角色`}
                      className="px-2 py-1 text-xs rounded border border-border bg-input"
                    >
                      {roleOptions.map((r) => (
                        <option key={r.value} value={r.value}>
                          {r.label}
                        </option>
                      ))}
                    </select>
                  ) : (
                    <span className="text-xs">{m.role}</span>
                  )}
                </td>
                <td className="px-6 py-3 text-xs text-muted-foreground">
                  {m.joinedAt
                    ? m.joinedAt instanceof Date
                      ? m.joinedAt.toLocaleDateString()
                      : m.joinedAt
                    : '—'}
                </td>
                <td className="px-6 py-3">
                  {m.status && (
                    <span
                      className={[
                        'px-2 py-0.5 text-xs rounded',
                        m.status === 'active' && 'bg-success/15 text-success',
                        m.status === 'invited' && 'bg-info/15 text-info',
                        m.status === 'suspended' && 'bg-destructive/15 text-destructive',
                      ]
                        .filter(Boolean)
                        .join(' ')}
                    >
                      {m.status}
                    </span>
                  )}
                </td>
                <td className="px-6 py-3 text-right">
                  {canRemove && (
                    <button
                      type="button"
                      onClick={() => onRemove?.(m.id)}
                      aria-label={`移除 ${m.email}`}
                      className="px-2 py-1 text-xs rounded text-destructive hover:bg-destructive/15"
                    >
                      移除
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
