/**
 * OLoginPage v6.0 — 重写
 * 修复:
 * - OAuth 按钮用真实 SVG 图标(Google/GitHub/WeChat)
 * - 手机号+按钮横排改为正确 flex 布局
 * - 验证码输入大字显示,更易用
 * - 整体卡片视觉更突出
 */
'use client';

import { useState, type FormEvent, type ReactNode } from 'react';
import { OAuthShell } from '../shell/OAuthShell';
import { AuthRegisterForm, type AuthRegisterData } from './_AuthRegisterForm';

export type LoginMethod = 'phone' | 'wechat' | 'email' | 'google' | 'github';

export interface OLoginPageProps {
  title?: string;
  subtitle?: string;
  methods?: LoginMethod[];
  onSendCode?: (phone: string) => void | Promise<void>;
  onPhoneLogin?: (data: { phone: string; code: string }) => void | Promise<void>;
  onEmailLogin?: (data: { email: string; password: string; remember: boolean }) => void | Promise<void>;
  onOAuth?: (provider: string) => void;
  wechatQrUrl?: string;
  errorMessage?: string;
  loading?: boolean;
  links?: ReactNode;
  topSlot?: ReactNode;
  /**
   * 注册回调(v1.7.0)。提供后,登录卡片顶部出现「登录 / 注册」切换。
   * 注册 tab 复用 OSignupPage 同款表单(显示名 + 邮箱 + 密码强度 + 确认密码)。
   */
  onEmailRegister?: (data: AuthRegisterData) => void | Promise<void>;
  /** 是否显示注册 tab。默认 true,但仅在提供 onEmailRegister 时实际渲染。 */
  showRegister?: boolean;
  /** 注册态的错误信息(与登录态 errorMessage 分开,避免串台)。 */
  registerError?: string;
}

const DEFAULT_METHODS: LoginMethod[] = ['phone', 'wechat', 'email', 'google', 'github'];

