const OAUTH_META: Record<string, { Icon: () => JSX.Element; label: string; bg?: string; color?: string }> = {
  google: { Icon: GoogleIcon, label: 'Google' },
  github: { Icon: GitHubIcon, label: 'GitHub' },
};

const TAB_LABEL: Record<LoginMethod, string> = {
  phone:  '手机验证码',
  wechat: '微信扫码',
  email:  '邮箱密码',
  google: 'Google',
  github: 'GitHub',
};

// ── 手机验证码 ─────────────────────────────────────
function PhoneTab({
  onSendCode, onPhoneLogin, loading, error,
}: {
  onSendCode?: (p: string) => void | Promise<void>;
  onPhoneLogin?: (d: { phone: string; code: string }) => void | Promise<void>;
  loading?: boolean;
  error?: string;
}) {
  const [phone,   setPhone]   = useState('');
  const [code,    setCode]    = useState('');
  const [sent,    setSent]    = useState(false);
  const [sending, setSending] = useState(false);
  const [countdown, setCountdown] = useState(0);

  const sendCode = async () => {
    if (!phone.trim() || sending) return;
    setSending(true);
    await onSendCode?.(phone);
    setSending(false);
    setSent(true);
    // 60s 倒计时
    let t = 60;
    setCountdown(t);
    const timer = setInterval(() => {
      t--;
      setCountdown(t);
      if (t <= 0) { clearInterval(timer); setSent(false); }
    }, 1000);
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    onPhoneLogin?.({ phone, code });
  };

  return (
    <form onSubmit={submit} className="oui-form" noValidate>
      <label className="oui-label">
        手机号
        <div style={{ display: 'flex', gap: '8px', alignItems: 'stretch' }}>
          <input
            type="tel" inputMode="numeric" autoComplete="tel"
            value={phone} onChange={e => setPhone(e.target.value)}
            placeholder="请输入手机号"
            className="oui-input" style={{ flex: 1, minWidth: 0 }}
          />
          <button
            type="button"
            onClick={sendCode}
            disabled={sending || !phone.trim() || countdown > 0}
            style={{
              flexShrink: 0,
              padding: '0 14px',
              borderRadius: 'var(--radius, 0.5rem)',
              border: '1.5px solid var(--border)',
              background: countdown > 0 ? 'var(--muted)' : 'var(--primary)',
              color: countdown > 0 ? 'var(--muted-foreground)' : 'var(--primary-foreground)',
              fontSize: 'var(--text-sm, 0.875rem)',
              fontWeight: 600,
              cursor: countdown > 0 || !phone.trim() ? 'not-allowed' : 'pointer',
              whiteSpace: 'nowrap',
              opacity: !phone.trim() ? 0.45 : 1,
              transition: 'all var(--duration-fast, 100ms)',
            }}
          >
            {sending ? '发送中…' : countdown > 0 ? `${countdown}s` : '获取验证码'}
          </button>
        </div>
      </label>

      {sent && (
        <label className="oui-label">
          验证码
          <input
            type="text" inputMode="numeric" maxLength={6}
            value={code} onChange={e => setCode(e.target.value.replace(/\D/g, ''))}
            placeholder="请输入 6 位验证码"
            autoFocus
            className="oui-input"
            style={{
              letterSpacing: '0.25em',
              textAlign: 'center',
              fontSize: '1.25rem',
              fontWeight: 700,
              fontVariantNumeric: 'tabular-nums',
            }}
          />
        </label>
      )}

      {error && <div role="alert" className="oui-error-alert">{error}</div>}

      <button
        type="submit"
        disabled={loading || !sent || code.length < 4}
        className="oui-btn-primary oui-w-full"
      >
        {loading ? '登录中...': '登录'}
      </button>
    </form>
  );
}

// ── 微信扫码 ──────────────────────────────────────
function WechatTab({ qrUrl, onOAuth }: { qrUrl?: string; onOAuth?: (p: string) => void }) {
  return (
    <div className="oui-qr-box">
      {qrUrl ? (
        <img src={qrUrl} alt="微信登录二维码" className="oui-qr-image" />
      ) : (
        <div
          className="oui-qr-placeholder"
          onClick={() => onOAuth?.('wechat')}
          style={{ cursor: 'pointer' }}
          role="button" tabIndex={0}
          onKeyDown={e => e.key === 'Enter' && onOAuth?.('wechat')}
          aria-label="微信登录"
        >
          <WeChatIcon />
          <div style={{ fontWeight: 600, marginTop: '8px' }}>点击唤起微信授权</div>
          <div style={{ marginTop: '4px', fontSize: 'var(--text-xs)', opacity: 0.7 }}>
            或配置 wechatQrUrl 显示二维码
          </div>
        </div>
      )}
      <p className="oui-qr-hint">
        {qrUrl ? '打开微信 → 扫一扫 完成登录' : '需要后端配置微信 OAuth'}
      </p>
    </div>
  );
}

// ── 邮箱密码 ──────────────────────────────────────
function EmailTab({
  onEmailLogin, loading, error,
}: {
  onEmailLogin?: (d: { email: string; password: string; remember: boolean }) => void | Promise<void>;
  loading?: boolean;
  error?: string;
}) {
  const [email,    setEmail]    = useState('');
  const [password, setPassword] = useState('');
  const [remember, setRemember] = useState(true);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    onEmailLogin?.({ email, password, remember });
  };

  return (
    <form onSubmit={submit} className="oui-form" noValidate>
      <label className="oui-label">
        邮箱 / Email
        <input type="email" required autoComplete="email"
          value={email} onChange={e => setEmail(e.target.value)}
          placeholder="your@email.com"
          className="oui-input" />
      </label>
      <label className="oui-label">
        密码 / Password
        <input type="password" required autoComplete="current-password"
          value={password} onChange={e => setPassword(e.target.value)}
          placeholder="请输入密码"
          className="oui-input" />
      </label>
      <div className="oui-row-between">
        <label className="oui-label-row">
          <input type="checkbox" checked={remember} onChange={e => setRemember(e.target.checked)} />
          <span>记住我</span>
        </label>
      </div>
      {error && <div role="alert" className="oui-error-alert">{error}</div>}
      <button type="submit" disabled={loading} className="oui-btn-primary oui-w-full">
        {loading ? '登录中...': '登录'}
      </button>
    </form>
  );
}

type AuthMode = 'login' | 'register';

// ── 主组件 ────────────────────────────────────────
export default function OLoginPage({
  title = '登录',
  subtitle,
  methods = DEFAULT_METHODS,
  onSendCode,
  onPhoneLogin,
  onEmailLogin,
  onOAuth,
  wechatQrUrl,
  errorMessage,
  loading,
  links,
  topSlot,
  onEmailRegister,
  showRegister = true,
  registerError,
}: OLoginPageProps) {
  const tabMethods   = methods.filter(m => !['google', 'github'].includes(m));
  const oauthMethods = methods.filter(m => ['google', 'github'].includes(m));
  const [activeTab, setActiveTab] = useState<LoginMethod>(tabMethods[0] ?? 'phone');
  const [mode, setMode] = useState<AuthMode>('login');

  // 注册能力只有在提供 onEmailRegister 且 showRegister 时才出现
  const registerEnabled = showRegister && !!onEmailRegister;

  return (
    <OAuthShell title={title} subtitle={subtitle} topSlot={topSlot}>
      <div className="oui-form">

        {/* 登录 / 注册 模式切换(v1.7.0) */}
        {registerEnabled && (
          <div className="oui-auth-modeswitch" role="tablist" aria-label="登录或注册">
            <button
              type="button"
              role="tab"
              aria-selected={mode === 'login'}
              className="oui-auth-modetab"
              onClick={() => setMode('login')}
            >
              登录
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={mode === 'register'}
              className="oui-auth-modetab"
              onClick={() => setMode('register')}
            >
              注册
            </button>
          </div>
        )}

        {mode === 'register' && registerEnabled ? (
          /* ── 注册态:复用 OSignupPage 同款表单 ── */
          <AuthRegisterForm
            {...(onEmailRegister && { onSubmit: onEmailRegister })}
            {...(registerError && { errorMessage: registerError })}
            {...(loading !== undefined && { loading })}
            submitLabel="注册"
            loadingLabel="注册中..."
          />
        ) : (
          /* ── 登录态 ── */
          <>
            {/* 登录方式 Tab 切换 */}
            {tabMethods.length > 1 && (
              <div className="oui-login-tabs" role="tablist">
                {tabMethods.map(m => (
                  <button
                    key={m}
                    type="button"
                    role="tab"
                    aria-selected={activeTab === m}
                    className="oui-login-tab"
                    onClick={() => setActiveTab(m)}
                  >
                    {TAB_LABEL[m]}
                  </button>
                ))}
              </div>
            )}

            {/* Tab 内容 */}
            {activeTab === 'phone'  && <PhoneTab  onSendCode={onSendCode}   onPhoneLogin={onPhoneLogin} loading={loading} error={errorMessage} />}
            {activeTab === 'wechat' && <WechatTab qrUrl={wechatQrUrl}       onOAuth={onOAuth} />}
            {activeTab === 'email'  && <EmailTab  onEmailLogin={onEmailLogin} loading={loading} error={errorMessage} />}

            {/* OAuth 第三方登录 */}
            {oauthMethods.length > 0 && (
              <>
                <div className="oui-divider">或</div>
                <div className="oui-oauth-grid">
                  {oauthMethods.map(m => {
                    const meta = OAUTH_META[m];
                    if (!meta) return null;
                    return (
                      <button
                        key={m}
                        type="button"
                        className="oui-oauth-btn"
                        onClick={() => onOAuth?.(m)}
                        disabled={loading}
                        aria-label={`使用 ${meta.label} 登录`}
                      >
                        <meta.Icon />
                        <span>{meta.label}</span>
                      </button>
                    );
                  })}
                </div>
              </>
            )}
          </>
        )}

        {/* 底部链接(两态共用) */}
        {links && (
          <div style={{
            textAlign: 'center',
            fontSize: 'var(--text-xs, 0.75rem)',
            color: 'var(--muted-foreground)',
            paddingTop: 'var(--space-1, 4px)',
          }}>
            {links}
          </div>
        )}
      </div>
    </OAuthShell>
  );
}
