/**
 * OOnboardingPage — 新用户引导页(分步).
 */
import { useState, type ReactNode } from 'react';

export interface OnboardingStep {
  id: string;
  title: string;
  description?: string;
  content: ReactNode;
  /** 完成此步骤的回调(返回 false 不前进)。 */
  onComplete?: () => boolean | Promise<boolean> | void;
}

export interface OOnboardingPageProps {
  steps: OnboardingStep[];
  /** 全部完成后回调。 */
  onFinish?: () => void;
  /** 跳过回调。 */
  onSkip?: () => void;
  allowSkip?: boolean;
  title?: string;
}

export default function OOnboardingPage({
  steps,
  onFinish,
  onSkip,
  allowSkip = true,
  title = '欢迎',
}: OOnboardingPageProps) {
  const [idx, setIdx] = useState(0);
  const step = steps[idx];
  if (!step) return null;
  const isLast = idx === steps.length - 1;

  const next = async () => {
    const ok = (await step.onComplete?.()) ?? true;
    if (ok === false) return;
    if (isLast) onFinish?.();
    else setIdx((i) => i + 1);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-4 py-12 bg-background @container">
      <div className="w-full max-w-lg flex flex-col gap-4">
        <header className="text-center">
          <h1 className="text-2xl font-semibold">{title}</h1>
          <div
            className="flex items-center justify-center gap-1 mt-2"
            role="progressbar"
            aria-valuenow={idx + 1}
            aria-valuemin={1}
            aria-valuemax={steps.length}
            aria-label={`步骤 ${idx + 1} / ${steps.length}`}
          >
            {steps.map((s, i) => (
              <span
                key={s.id}
                className={[
                  'h-1.5 rounded-full transition-all',
                  i === idx ? 'w-8 bg-primary' : 'w-2 bg-muted',
                ].join(' ')}
                aria-hidden="true"
              />
            ))}
          </div>
        </header>
        <section className="p-6 rounded-lg border border-border bg-card">
          <h2 className="text-base font-semibold mb-1">{step.title}</h2>
          {step.description && (
            <p className="text-sm text-muted-foreground mb-4">{step.description}</p>
          )}
          <div>{step.content}</div>
        </section>
        <footer className="flex items-center justify-between">
          {allowSkip && !isLast ? (
            <button
              type="button"
              onClick={onSkip}
              className="text-xs text-muted-foreground hover:text-foreground"
            >
              跳过
            </button>
          ) : (
            <span />
          )}
          <div className="flex items-center gap-2">
            {idx > 0 && (
              <button
                type="button"
                onClick={() => setIdx((i) => i - 1)}
                className="px-3 py-1.5 text-sm rounded border border-border"
              >
                上一步
              </button>
            )}
            <button
              type="button"
              onClick={next}
              className="px-4 py-1.5 text-sm rounded bg-primary text-primary-foreground"
            >
              {isLast ? '完成' : '下一步'}
            </button>
          </div>
        </footer>
      </div>
    </div>
  );
}
